def transform(grid):
    """Extend the 2x2 zero marker into full rows/columns, preserving 2s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = None
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0 for rr in (r, r + 1) for cc in (c, c + 1)):
                marker = (r, c)
                break
        if marker is not None:
            break
    if marker is None:
        return out
    r, c = marker
    for rr in (r, r + 1):
        for cc in range(w):
            if grid[rr][cc] != 2:
                out[rr][cc] = 0
    for cc in (c, c + 1):
        for rr in range(h):
            if grid[rr][cc] != 2:
                out[rr][cc] = 0
    return out
